/*!
 * jquery.counterup.js 1.0
 * Copyright 2013, Benjamin Intal http://gambit.ph @bfintal
 * Released under the GPL v2 License
 *
 * Date: Nov 26, 2013
 * Kit note: waypoint.triggerOnce is a Waypoints 2 option. Waypoints 4
 * (jQuery 3) uses waypoint.destroy() so each counter still animates once.
 */
(function ($) {
  "use strict";
  $.fn.counterUp = function (options) {
    var settings = $.extend({ time: 400, delay: 10 }, options);
    return this.each(function () {
      var $el = $(this);
      var run = function () {
        var nums = [];
        var divisions = settings.time / settings.delay;
        var num = $el.text();
        var isComma = /[0-9]+,[0-9]+/.test(num);
        num = num.replace(/,/g, "");
        var isInt = /^[0-9]+$/.test(num);
        var isFloat = /^[0-9]+\.[0-9]+$/.test(num);
        var decimalPlaces = isFloat ? (num.split(".")[1] || []).length : 0;
        var i;
        var newNum;
        for (i = divisions; i >= 1; i--) {
          newNum = parseInt(num / divisions * i, 10);
          if (isFloat) {
            newNum = parseFloat(num / divisions * i).toFixed(decimalPlaces);
          }
          if (isComma) {
            while (/(\d+)(\d{3})/.test(newNum.toString())) {
              newNum = newNum.toString().replace(/(\d+)(\d{3})/, "$1,$2");
            }
          }
          nums.unshift(newNum);
        }
        $el.data("counterup-nums", nums);
        $el.text("0");
        var tick = function () {
          var leftover = $el.data("counterup-nums");
          if (!leftover || !leftover.length) {
            return;
          }
          $el.text(leftover.shift());
          if (leftover.length) {
            setTimeout(tick, settings.delay);
          } else {
            $el.data("counterup-nums", null);
          }
        };
        setTimeout(tick, settings.delay);
      };
      $el.waypoint(function () {
        run();
        if (this && typeof this.destroy === "function") {
          this.destroy();
        }
      }, { offset: "100%" });
    });
  };
})(jQuery);
